#!/usr/bin/env bash
# Auto-generated by main.py.
# Loads decision-tree nodes into a BPF map via bpftool.
#
# Usage: sudo ./update_params.sh <map_id>
#
# Map value layout (4 bytes, little-endian):
#   bytes 0-3 : node value (__u32 LE)

if [ -z "$1" ]; then
    echo "Usage: sudo $0 <map_id>"
    exit 1
fi

MAP_ID="$1"

# node 0: feat_id=3 thresh=210 pass_left=1 pass_right=0
bpftool map update id "$MAP_ID" key hex 00 00 00 00 value hex 0E D2 00 00

# node 1: feat_id=0 thresh=49118 pass_left=1 pass_right=1
bpftool map update id "$MAP_ID" key hex 01 00 00 00 value hex 03 DE BF 00

# node 2: feat_id=2 thresh=11 pass_left=1 pass_right=0
bpftool map update id "$MAP_ID" key hex 02 00 00 00 value hex 0A 0B 00 00

# node 3: feat_id=2 thresh=11 pass_left=1 pass_right=0
bpftool map update id "$MAP_ID" key hex 03 00 00 00 value hex 0A 0B 00 00

# node 4: feat_id=1 thresh=40 pass_left=1 pass_right=1
bpftool map update id "$MAP_ID" key hex 04 00 00 00 value hex 07 28 00 00

# node 5: feat_id=1 thresh=261 pass_left=1 pass_right=1
bpftool map update id "$MAP_ID" key hex 05 00 00 00 value hex 07 05 01 00

# node 6: feat_id=4 thresh=77379 pass_left=0 pass_right=1
bpftool map update id "$MAP_ID" key hex 06 00 00 00 value hex 11 43 2E 01

# node 7: feat_id=0 thresh=2791 pass_left=1 pass_right=1
bpftool map update id "$MAP_ID" key hex 07 00 00 00 value hex 03 E7 0A 00

# node 8: feat_id=1 thresh=1136 pass_left=1 pass_right=0
bpftool map update id "$MAP_ID" key hex 08 00 00 00 value hex 06 70 04 00

# node 9: leaf / undefined
bpftool map update id "$MAP_ID" key hex 09 00 00 00 value hex 00 00 00 00

# node 10: feat_id=3 thresh=0 pass_left=1 pass_right=1
