# node 11: leaf / undefined
bpftool map update id "$MAP_ID" key hex 0B 00 00 00 value hex 00 00 00 00

# node 12: feat_id=0 thresh=42074 pass_left=1 pass_right=1
bpftool map update id "$MAP_ID" key hex 0C 00 00 00 value hex 03 5A A4 00

